// Simplified from Struts2 Jakarta multipart parser, pre-patch.
public void parse(HttpServletRequest req) {
    try {
        upload.parseRequest(req);
    } catch (FileUploadException e) {
        String contentType = req.getContentType();
        // Build a localized error that embeds the bad Content-Type.
        String msg = LocalizedTextUtil.findText(
            getClass(), "struts.messages.upload.error.parse",
            locale, "Error", new Object[]{ contentType });
        addActionError(msg);   // findText evaluates %{...} as OGNL
    }
}

